#ifndef TRADE_CDR_H
#define TRADE_CDR_H

/*
 * Minimal XCDR1 codec for the interop type in Trade.idl:
 *
 *   struct Trade { string symbol; double price; long volume; };
 *
 * A real application would use the code generated by idlc / fastddsgen. Here
 * we encode/parse by hand so the network-bridge side of the example stays free
 * of generated code and builds anywhere. Assumes little-endian (x86 / arm64)
 * and 4/8-byte CDR alignment, matching the on-wire body RTPS carries (no
 * encapsulation header).
 */

#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef struct trade_value {
    char symbol[64];
    double price;
    int32_t volume;
} trade_value_t;

/* Encode into buf; returns the number of bytes written (<= 64 for sane
 * inputs). */
static inline size_t trade_encode(unsigned char *buf, const trade_value_t *v)
{
    size_t off = 0;
    uint32_t len = (uint32_t)strlen(v->symbol) + 1; /* includes NUL */

    memcpy(buf + off, &len, 4);
    off += 4;
    memcpy(buf + off, v->symbol, len);
    off += len;
    while (off % 4 != 0) { /* pad to 4 */
        buf[off++] = 0;
    }
    while (off % 8 != 0) { /* align double to 8 */
        buf[off++] = 0;
    }
    memcpy(buf + off, &v->price, 8);
    off += 8;
    memcpy(buf + off, &v->volume, 4);
    off += 4;
    return off;
}

/* Decode a body produced by trade_encode (or by Cyclone). Returns 0 or -1. */
static inline int trade_decode(const void *data, size_t size, trade_value_t *v)
{
    const unsigned char *buf = (const unsigned char *)data;
    size_t off = 0;
    uint32_t len;

    if (size < 8) {
        return -1;
    }
    memcpy(&len, buf, 4);
    off += 4;
    if (len == 0 || len > sizeof(v->symbol) || off + len > size) {
        return -1;
    }
    memcpy(v->symbol, buf + off, len);
    v->symbol[len - 1] = '\0';
    off += len;
    while (off % 8 != 0) { /* skip padding */
        off++;
    }
    if (off + 12 > size) {
        return -1;
    }
    memcpy(&v->price, buf + off, 8);
    off += 8;
    memcpy(&v->volume, buf + off, 4);
    return 0;
}

#endif /* TRADE_CDR_H */
